import sys
M = 1_000_000_007

def fib(n):
    a, b = 0, 1  # F(0), F(1)
    for bit in bin(n)[2:]:
        c = a * ((b << 1) - a) % M
        d = (a * a + b * b) % M
        if bit == '1':
            a, b = d, (c + d) % M
        else:
            a, b = c, d
    return a

if __name__ == "__main__":
    print(fib(int(sys.argv[1])))

import sys
M = 1_000_000_007
P = 2 * (M + 1)  # Pisano period of M divides 2(M+1) since M is prime, M % 5 == 2

def fib(n):
    n %= P
    a, b = 0, 1  # F(0), F(1)
    for bit in bin(n)[2:]:
        c = a * ((b << 1) - a) % M
        d = (a * a + b * b) % M
        if bit == '1':
            a, b = d, (c + d) % M
        else:
            a, b = c, d
    return a

if __name__ == "__main__":
    print(fib(int(sys.argv[1])))
